rulesets.pack-1:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /c_float_div_is_float/{doc} {
      allow get: if (3.0 / 2) is float;
    }
    match /c_point_one_plus_point_two/{doc} {
      allow get: if 0.1 + 0.2 == 0.3;
    }
    match /c_float_of_int/{doc} {
      allow get: if float(2) == 2.0 && float(2) is float;
    }
    match /c_int_of_int/{doc} {
      allow get: if int(2) is int;
    }
    match /c_neg_zero/{doc} {
      allow get: if -0.0 == 0.0;
    }
    match /c_float_mod/{doc} {
      allow get: if 5.5 % 2 == 1.5;
    }
    match /c_neg_mod/{doc} {
      allow get: if -5 % 3 == -2;
    }
    match /c_unary_minus_field/{doc} {
      allow get: if -resource.data.n == -1;
    }
    match /c_unary_minus_string/{doc} {
      allow get: if -'a' == 'a';
    }
    match /c_int_float_list_eq/{doc} {
      allow get: if [1] == [1.0];
    }
    match /c_nan_eq_nan/{doc} {
      allow get: if (0.0 / 0.0) == (0.0 / 0.0);
    }
    match /c_nan_ne_nan/{doc} {
      allow get: if (0.0 / 0.0) != (0.0 / 0.0);
    }
    match /c_abs_int/{doc} {
      allow get: if math.abs(-1) == 1 && math.abs(-1) is int;
    }
    match /c_abs_float/{doc} {
      allow get: if math.abs(-1.5) == 1.5;
    }
    match /c_abs_int_min/{doc} {
      allow get: if math.abs(-9223372036854775807 - 1) < 0;
    }
    match /c_ceil_float/{doc} {
      allow get: if math.ceil(1.2) == 2.0 && math.ceil(1.2) is float;
    }
    match /c_ceil_int/{doc} {
      allow get: if math.ceil(1) == 1.0 && math.ceil(1) is float;
    }
    match /c_round_half_up/{doc} {
      allow get: if math.round(2.5) == 3 && math.round(2.5) is int;
    }
    match /c_round_neg_half/{doc} {
      allow get: if math.round(-2.5) == -2;
    }
    match /c_round_neg_half_away/{doc} {
      allow get: if math.round(-2.5) == -3;
    }
    match /c_round_nan/{doc} {
      allow get: if math.round(0.0 / 0.0) == 0;
    }
    match /c_round_inf/{doc} {
      allow get: if math.round(1.0 / 0.0) == 9223372036854775807;
    }
    match /c_sqrt/{doc} {
      allow get: if math.sqrt(4) == 2.0 && math.sqrt(4) is float;
    }
    match /c_sqrt_negative_nan/{doc} {
      allow get: if math.isNaN(math.sqrt(-1));
    }
    match /c_pow/{doc} {
      allow get: if math.pow(2, 10) == 1024.0 && math.pow(2, 10) is float;
    }
    match /c_pow_fraction/{doc} {
      allow get: if math.pow(4, 0.5) == 2.0;
    }
    match /c_isnan_int/{doc} {
      allow get: if math.isNaN(1) == false;
    }
    match /c_isinfinite/{doc} {
      allow get: if math.isInfinite(1.0 / 0.0);
    }
    match /c_abs_string/{doc} {
      allow get: if math.abs('a') == 1;
    }
    match /c_abs_two_args/{doc} {
      allow get: if math.abs(1, 2) == 1;
    }
    match /c_trunc_absent/{doc} {
      allow get: if math.trunc(1.5) == 1.0;
    }
    match /c_sha256_string/{doc} {
      allow get: if hashing.sha256('abc') == b'\xba\x78\x16\xbf\x8f\x01\xcf\xea\x41\x41\x40\xde\x5d\xae\x22\x23\xb0\x03\x61\xa3\x96\x17\x7a\x9c\xb4\x10\xff\x61\xf2\x00\x15\xad';
    }
    match /c_sha256_bytes/{doc} {
      allow get: if hashing.sha256(b'abc') == b'\xba\x78\x16\xbf\x8f\x01\xcf\xea\x41\x41\x40\xde\x5d\xae\x22\x23\xb0\x03\x61\xa3\x96\x17\x7a\x9c\xb4\x10\xff\x61\xf2\x00\x15\xad';
    }
    match /c_md5_hex_upper/{doc} {
      allow get: if hashing.md5('abc').toHexString() == '900150983CD24FB0D6963F7D28E17F72';
    }
    match /c_md5_hex_lower/{doc} {
      allow get: if hashing.md5('abc').toHexString() == '900150983cd24fb0d6963f7d28e17f72';
    }
    match /c_crc32/{doc} {
      allow get: if hashing.crc32('abc') == b'\x35\x24\x41\xc2';
    }
    match /c_crc32_is_bytes/{doc} {
      allow get: if hashing.crc32('abc') is bytes;
    }
    match /c_crc32c_is_bytes/{doc} {
      allow get: if hashing.crc32c('abc') is bytes;
    }
    match /c_sha256_int/{doc} {
      allow get: if hashing.sha256(1) is bytes;
    }
    match /c_bytes_size/{doc} {
      allow get: if b'abc'.size() == 3;
    }
    match /c_bytes_hex_escape/{doc} {
      allow get: if b'\x00\xff'.size() == 2;
    }
    match /c_bytes_base64/{doc} {
      allow get: if b'abc'.toBase64() == 'YWJj';
    }
    match /c_bytes_base64_url/{doc} {
      allow get: if b'\xfb\xff'.toBase64() == '-_8=';
    }
    match /c_bytes_base64_std/{doc} {
      allow get: if b'\xfb\xff'.toBase64() == '+/8=';
    }
    match /c_bytes_compare/{doc} {
      allow get: if b'a' < b'b';
    }
    match /c_bytes_index/{doc} {
      allow get: if b'abc'[0] == 97;
    }
    match /c_latlng_value/{doc} {
      allow get: if latlng.value(10.0, 20.0).latitude() == 10.0;
    }
    match /c_latlng_out_of_range/{doc} {
      allow get: if latlng.value(91.0, 0.0) is latlng;
    }
  }
}
